<script setup lang="ts">
import ProfileRecordView from '@/components/ProfileRecord.vue'
import AreaRecord from '@/components/AreaRecord.vue'
import MeasurementDetails from '@/components/MeasurementDetails.vue'
import { normalizeReport } from '@/utils/contracts'
import { computed, onMounted, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { useRoute, useRouter } from 'vue-router'
import { getTaskSubmissions, getTeacherSubmission, getTeacherTask, gradeSubmission } from '@/api/teacher'
import type { TeacherSubmission, TeacherTask } from '@/types/teacher'
import { displayTime } from '@/utils/student'
const route=useRoute(),router=useRouter(),task=ref<TeacherTask>(),list=ref<TeacherSubmission[]>([]),selected=ref<TeacherSubmission>(),loading=ref(false),grading=ref(false),grade=ref({score:null as number|null,feedback:''});const canGrade=computed(()=>selected.value?.status==='SUBMITTED')
async function load(){loading.value=true;try{const [t,s]=await Promise.all([getTeacherTask(String(route.params.taskId)),getTaskSubmissions(String(route.params.taskId))]);task.value=t;list.value=s}catch(e){ElMessage.error(e instanceof Error?e.message:'提交记录加载失败')}finally{loading.value=false}}
async function select(item:TeacherSubmission){try{selected.value=await getTeacherSubmission(item.id);selected.value.reportContent=normalizeReport(selected.value.reportContent);grade.value={score:selected.value.score,feedback:selected.value.feedback||''}}catch(e){ElMessage.error(e instanceof Error?e.message:'作业详情加载失败')}}
async function submitGrade(){if(grading.value||!selected.value||!canGrade.value)return;if(grade.value.score===null||grade.value.score<0||grade.value.score>100){ElMessage.warning('分数必须在 0 到 100 之间');return}grading.value=true;try{await gradeSubmission(selected.value.id,{score:grade.value.score,feedback:grade.value.feedback});await load();await select(selected.value);ElMessage.success('评分已保存')}catch(e){const status=(e as {response?:{status?:number}}).response?.status;ElMessage.error(status===403?'无评分权限':status===409?'该作业状态已变化，请刷新后重试':e instanceof Error?e.message:'评分保存失败')}finally{grading.value=false}}
onMounted(load)
</script>
<template><main class="page"><div class="head"><div><p>教师 / 实训任务</p><h1>{{task?.title||'学生提交'}}</h1></div><el-button @click="router.push('/teacher/tasks')">返回任务</el-button></div><div class="grid"><el-card v-loading="loading"><template #header>学生提交</template><el-table :data="list" highlight-current-row @row-click="select"><el-table-column prop="studentName" label="学生"/><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.status==='SUBMITTED'?'success':'info'">{{row.status==='SUBMITTED'?'已提交':'草稿'}}</el-tag></template></el-table-column><el-table-column label="提交时间" width="160"><template #default="{row}">{{displayTime(row.submittedAt)}}</template></el-table-column><el-table-column label="分数" width="80"><template #default="{row}">{{row.score??'-'}}</template></el-table-column><el-table-column label="评分时间" width="160"><template #default="{row}">{{displayTime(row.gradedAt)}}</template></el-table-column></el-table><el-empty v-if="!loading&&!list.length" description="暂无学生提交"/></el-card><el-card><template #header>作业详情与评分</template><el-empty v-if="!selected" description="选择一份学生作业查看"/><template v-else><el-alert v-if="selected.status!=='SUBMITTED'" title="该作业尚未提交，不能评分" type="info" :closable="false"/><el-descriptions :column="1" border><el-descriptions-item label="现场概况">{{selected.reportContent?.overview||'-'}}</el-descriptions-item><el-descriptions-item label="勘验过程">{{selected.reportContent?.process||'-'}}</el-descriptions-item><el-descriptions-item label="物证描述">{{selected.reportContent?.evidenceDescription||'-'}}</el-descriptions-item><el-descriptions-item label="初步结论">{{selected.reportContent?.preliminaryConclusion||'-'}}</el-descriptions-item><el-descriptions-item label="学生标记">{{selected.marks?.length||0}} 条</el-descriptions-item><el-descriptions-item label="学生测距">{{selected.measurements?.length||0}} 条</el-descriptions-item></el-descriptions><MeasurementDetails v-for="(measurement,index) in selected.measurements" :key="index" :value="measurement"/><h3>区域测量 {{selected.areaMeasurements?.length||0}} 条</h3><AreaRecord v-for="item in selected.areaMeasurements" :key="item.id" :value="item"/><h3>剖面 {{selected.profiles?.length||0}} 条</h3><ProfileRecordView v-for="item in selected.profiles" :key="item.id" :value="item"/><el-divider>基础评分</el-divider><el-form label-position="top"><el-form-item label="分数（0–100）"><el-input-number v-model="grade.score" :min="0" :max="100" :disabled="!canGrade"/></el-form-item><el-form-item label="评语"><el-input v-model="grade.feedback" :disabled="!canGrade" type="textarea" :rows="4"/></el-form-item><el-button type="primary" :disabled="!canGrade" :loading="grading" @click="submitGrade">保存评分</el-button></el-form></template></el-card></div></main></template>
<style scoped>.page{max-width:1440px;min-height:100vh;margin:auto;padding:36px 32px}.head{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:24px}.head p{margin:0;color:#64748b;font-size:13px}h1{margin:7px 0;color:#142d4d}.grid{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(320px,.9fr);gap:20px}.el-descriptions{font-size:13px}:deep(.el-table .cell){white-space:normal}@media(max-width:900px){.page{padding:24px 16px}.grid{grid-template-columns:1fr}}</style>
